지역 발전·경험·능력 강조홍성현 충남도의원 예비후보가 선거사무소 개소식에서 국민의힘 도·시의원 예비후보자들과 기념 촬영을 하고 있다. /홍성현 후보 캠프[더팩트ㅣ천안=정효기 기자] 홍성현 국민의힘 충남도의원 예비후보(천안시 제1선거구)의 선거사무소 개소식이 18일 성황리에 열렸다.이날 행사에는 강승규 국민의힘 충남도당 위원장, 조미선·이정만·정도희 국민의힘 천안시 당협위원장, 박상돈·성무용 전 천안시장, 도·시의원, 당원과 시민 등 1000여 명이 참석해 뜨거운 열기를 보였다.지역 선거구에 출마하는 국민의힘 예비후보자들도 자리를 함께하며 힘을 보탰다.홍 후보는 개소식에서 "당이 어려운 상황이지만 지역 구석구석을 다니며 주민들의 목소리를 경청하고 그 물음에 답해야 한다"며 "더 많이 귀 기울이고 명확하고 풍부한 답변을 제시하겠다"고 강조했다.이어 그는 "서로에게 서운한 감정이 있더라도 우리 모두는 원팀"이라며 "승리를 위해 한마음으로 최선을 다해야 한다"고 당원 결집을 호소했다.홍 후보는 "충남과 천안의 도약, 지역 발전을 위해 다가오는 제9회 동시지방선거에서 각 정당의 출마자를 면밀히 살펴야 한다"며 "정당도 중요하지만 더 중요한 것은 출마자의 경험과 능력인 만큼 잘 판단해 선택해 달라"고 당부했다.홍 후보는 현재 충남도의회 의장으로, 충남도의원 3선 경력을 바탕으로 4선에 도전하고 있으며 국민의힘 충남도당 공약개발위원장을 맡고 있다.tfcc2024@tf.co.kr 발로 뛰는 <더팩트>는 24시간 여러분의 제보를 기다립니다. · 카카오톡: '더팩트제보' 검색 · 이메일: jebo@tf.co.kr · 뉴스 홈페이지: https://talk.tf.co.kr/bbs/report/write · 네이버 메인 더팩트 구독하고 [특종보자→] · 그곳이 알고싶냐? [영상보기→] AD try { var PopularNewsSrc = "<dt>인기기사</dt>"; for (var i = 0; i < POPULAR_NEWS.length; i++) { PopularNewsSrc += "<dd>· <a href=\""+POPULAR_NEWS[i].link+"\">"+POPULAR_NEWS[i].title+"</a></dd>"; } document.write(PopularNewsSrc); } catch(e){} window._taboola = window._taboola || []; _taboola.push({ mode: 'alternating-thumbnails-a', container: 'taboola-below-article-thumbnails-new', placement: 'Below Article Thumbnails New', target_type: 'mix' }); try { var EditorsChoiceSrc = "<dt>Editor's Choice</dt>"; EditorsChoiceSrc += "<dd><a href=\""+TF_MAIN_TOP_NEWS[0].link+"\">"+TF_MAIN_TOP_NEWS[0].title+"</a></dd>"; EditorsChoiceSrc += "<dd><a href=\""+TF_MAIN_MIDTOP_NEWS1[0].link+"\">"+TF_MAIN_MIDTOP_NEWS1[0].title+"</a></dd>"; EditorsChoiceSrc += "<dd><a href=\""+TF_MAIN_MIDTOP_NEWS1[1].link+"\">"+TF_MAIN_MIDTOP_NEWS1[1].title+"</a></dd>"; EditorsChoiceSrc += "<dd><a href=\""+TF_MAIN_MIDTOP_NEWS1[2].link+"\">"+TF_MAIN_MIDTOP_NEWS1[2].title+"</a></dd>"; EditorsChoiceSrc += "<dd><a href=\""+TF_MAIN_MIDTOP_NEWS2[0].link+"\">"+TF_MAIN_MIDTOP_NEWS2[0].title+"</a></dd>"; document.write(EditorsChoiceSrc); } ca