[data-whatintent="touch"] #comment button, [data-whatintent="touch"] #comment button:focus {outline:0} /* titles */
.cmt-header::after {content:'';display:table;clear:both}
.cmt-header .titles {float:left;font-size:1.25rem;font-weight:normal;line-height:35px;color:#000}
.cmt-header .comment-count {font-weight:bold}
.cmt-header .my-cmt {float:right;font-size:.875rem;line-height:35px;color:rgba(0,0,0,.95)}
.cmt-header .my-cmt > i[class^="icon-"] {display:inline-block;overflow:hidden;width:15px;height:15px;font-size:.5rem;line-height:13px;color:#000;border:1px solid rgba(0,0,0,.5);border-radius:50%;text-align:center;vertical-align:middle} /* write */
